"""Coverage calibration, exact score filtering, priority and table sizing.

Validation coverage is evaluated with exact rational scores and bitset pattern
matching; the exact bank size is the number of distinct integer keys in the
union of the kept patterns' Cartesian products.
"""
from fractions import Fraction
import numpy as np

PADDING = 1514
VALUE_COUNT = 3029
VALUE_MAX = 3028


def _match_set(prefix, tables, length):
    """Bitmask (by pattern index) of patterns matched by any real-prefix window."""
    accumulated = 0
    first = tables[0]
    span = len(prefix) - length + 1
    for start in range(span):
        current = first[prefix[start]]
        if not current:
            continue
        for coordinate in range(1, length):
            current &= tables[coordinate][prefix[start + coordinate]]
            if not current:
                break
        accumulated |= current
    return accumulated


def _value_tables(patterns, length):
    """Table[coordinate][value] -> bitmask of patterns accepting that value."""
    count = len(patterns)
    values = np.arange(VALUE_COUNT, dtype=np.int64)
    tables = []
    for coordinate in range(length):
        low = np.array([pattern[coordinate][0] for pattern in patterns], dtype=np.int64)
        high = np.array([pattern[coordinate][1] for pattern in patterns], dtype=np.int64)
        accepted = (low[None, :] <= values[:, None]) & (values[:, None] <= high[None, :])
        packed = np.packbits(accepted, axis=1, bitorder='little')
        tables.append([int.from_bytes(packed[index].tobytes(), 'little')
                       for index in range(VALUE_COUNT)])
    return tables


def attach_hits(clusters, validation, classes):
    """Fill hits[c] for every cluster with the matching validation row counts."""
    for cluster in clusters:
        cluster['hits'] = [0] * classes
    rows_by_class = [[] for _ in range(classes)]
    for row in validation:
        prefix = row['values']
        cut = prefix.index(PADDING) if PADDING in prefix else len(prefix)
        if cut:
            rows_by_class[row['class']].append(tuple(prefix[:cut]))
    by_length = {}
    for cluster in clusters:
        by_length.setdefault(cluster['length'], []).append(cluster)
    for length, group in by_length.items():
        count = len(group)
        patterns = [cluster['range'] for cluster in group]
        tables = _value_tables(patterns, length)
        width = (count + 7) // 8
        for label in range(classes):
            hits = np.zeros(count, dtype=np.int64)
            cache = {}
            for prefix in rows_by_class[label]:
                if len(prefix) < length:
                    continue
                found = cache.get(prefix)
                if found is None:
                    found = _match_set(prefix, tables, length)
                    cache[prefix] = found
                if found:
                    bits = np.unpackbits(np.frombuffer(found.to_bytes(width, 'little'),
                                                      dtype=np.uint8),
                                         bitorder='little')[:count]
                    hits += bits
            for index, cluster in enumerate(group):
                cluster['hits'][label] = int(hits[index])


def score_clusters(clusters, validation, classes, threshold):
    """Exact Cin/(Cout+1/10000) score, kept flag and shared priority order."""
    totals = [0] * classes
    for row in validation:
        totals[row['class']] += 1
    limit = Fraction(*threshold)
    for cluster in clusters:
        target = cluster['class']
        inside = Fraction(cluster['hits'][target], totals[target])
        outside = Fraction(0)
        for label in range(classes):
            if label != target and totals[label]:
                share = Fraction(cluster['hits'][label], totals[label])
                if share > outside:
                    outside = share
        cluster['score'] = inside / (outside + Fraction(1, 10000))
        cluster['kept'] = cluster['score'] > limit
    kept = [cluster for cluster in clusters if cluster['kept']]
    kept.sort(key=lambda cluster: (-cluster['score'], cluster['id']))
    return kept


def _factor_size(factor):
    return sum(stop - start + 1 for start, stop in factor)


def _box_size(box):
    size = 1
    for factor in box:
        size *= _factor_size(factor)
    return size


def _split_interval(start, stop):
    """An inclusive interval with 1514 removed becomes at most two intervals."""
    if start <= PADDING <= stop:
        return ((start, PADDING - 1), (PADDING + 1, stop)) if start <= PADDING - 1 \
            else (((PADDING + 1, stop),) if stop >= PADDING + 1 else ())
    return ((start, stop),)


def _pattern_box(ranges):
    return tuple(tuple(_split_interval(start, stop)) for start, stop in ranges)


def _union_size(boxes, limit, memo):
    """Exact size of the union of boxes, reported as limit+1 when larger."""
    if not boxes:
        return 0
    if len(boxes) == 1:
        size = _box_size(boxes[0])
        return size if size <= limit else limit + 1
    cached = memo.get(boxes)
    if cached is not None:
        return cached
    events = []
    for box in boxes:
        for start, stop in box[0]:
            events.append((start, 1, box))
            events.append((stop + 1, 0, box))
    events.sort(key=lambda event: (event[0], event[1]))
    active = set()
    total = 0
    position = 0
    count = len(events)
    while position < count:
        spot = events[position][0]
        while position < count and events[position][0] == spot:
            _, kind, box = events[position]
            if kind:
                active.add(box)
            else:
                active.discard(box)
            position += 1
        if not active or position == count:
            continue
        following = events[position][0]
        reduced = tuple(sorted({box[1:] for box in active}))
        part = _union_size(reduced, limit, memo)
        if part > limit:
            memo[boxes] = limit + 1
            return limit + 1
        total += (following - spot) * part
        if total > limit:
            memo[boxes] = limit + 1
            return limit + 1
    memo[boxes] = total
    return total


def exact_key_count(clusters, capacity):
    """Distinct exact keys over every pattern length, clipped to capacity+1."""
    limit = capacity + 1
    by_length = {}
    for cluster in clusters:
        by_length.setdefault(cluster['length'], set()).add(_pattern_box(cluster['range']))
    total = 0
    memo = {}
    for boxes in by_length.values():
        total += _union_size(tuple(sorted(boxes)), limit, memo)
        if total > limit:
            break
    return total if total <= limit else limit
