"""Independent slow reference implementation of the v3 contract (brute force)."""
import math
from fractions import Fraction
from itertools import product
import numpy as np
from sklearn.tree import DecisionTreeClassifier

PADDING = 1514


def real_len(values):
    n = 0
    for v in values:
        if v == PADDING:
            break
        n += 1
    return n


def fragments_of(discovery, width):
    out = []
    for ri, row in enumerate(discovery):
        vals = row['values']
        acts = row['activation']
        n = real_len(vals)
        if n == 0:
            continue
        a = acts[:n]
        mean = Fraction(sum(a), n)
        var = Fraction(sum(x * x for x in a), n) - mean * mean
        high = []
        for i in range(n):
            d = a[i] - mean
            if var >= 0 and d > 0 and d * d > var:
                high.append(True)
            else:
                high.append(False)
        i = 0
        while i < n:
            if not high[i]:
                i += 1
                continue
            j = i
            while j < n and high[j]:
                j += 1
            run = j - i
            if run >= 2:
                if run <= width:
                    s, L = i, run
                else:
                    best = None
                    for off in range(run - width + 1):
                        sm = sum(a[i + off:i + off + width])
                        if best is None or sm > best:
                            best = sm
                            s = i + off
                    L = width
                out.append({'row': ri, 'start': s, 'length': L,
                            'class': row['class'],
                            'values': tuple(vals[s:s + L])})
            i = j
    return out


def distance_ok(a, b, eps):
    L = len(a)
    s = 0
    A = 0
    for x, y in zip(a, b):
        d = abs(x - y)
        if (x < PADDING < y) or (y < PADDING < x):
            d += 1000
        s += d * d
        if x == y:
            A += 1
    # sqrt(s/L)*(3/5)^A <= eps  <=>  s/L * 9^A <= eps^2
    return Fraction(s, L) * Fraction(9, 25) ** A <= eps * eps


def cluster(frags, classes, eps, ratio):
    groups = {}
    for idx, f in enumerate(frags):
        groups.setdefault((f['class'], f['length']), []).append(idx)
    counts = [0] * classes
    for f in frags:
        counts[f['class']] += 1
    out = {}
    noise = []
    for (c, L), members in groups.items():
        minpts = max(2, math.ceil(Fraction(counts[c]) * Fraction(*ratio)))
        neigh = {m: set() for m in members}
        for i, x in enumerate(members):
            for j, y in enumerate(members):
                if distance_ok(frags[x]['values'], frags[y]['values'], eps):
                    neigh[x].add(y)
        cores = [m for m in members if len(neigh[m]) >= minpts]
        if not cores:
            noise.extend(members)
            continue
        # components of the core graph
        comp = {}
        cid = 0
        unseen = set(cores)
        while unseen:
            stack = [min(unseen)]
            comp_members = []
            while stack:
                node = stack.pop()
                if node in comp:
                    continue
                comp[node] = cid
                comp_members.append(node)
                unseen.discard(node)
                for other in cores:
                    if other not in comp and other in neigh[node]:
                        stack.append(other)
            cid += 1
        label = {}
        for m in cores:
            label[m] = min(x for x in cores if comp[x] == comp[m])
        for m in members:
            if m in label:
                continue
            adj = [x for x in cores if x in neigh[m]]
            if adj:
                best = None
                for x in adj:
                    lb = label[x]
                    if best is None or lb < best:
                        best = lb
                label[m] = best
            else:
                noise.append(m)
        for m, lb in label.items():
            out.setdefault(lb, {'id': lb, 'class': c, 'members': [], 'core': []})
            out[lb]['members'].append(m)
            if m in cores:
                out[lb]['core'].append(m)
    clusters = []
    for k, v in out.items():
        v['members'].sort()
        v['core'].sort()
        v['length'] = frags[v['members'][0]]['length']
        clusters.append(v)
    clusters.sort(key=lambda x: x['id'])
    return clusters, sorted(noise)


def intervals_of(cluster, frags):
    seqs = [frags[i]['values'] for i in cluster['members']]
    L = len(seqs[0])
    n = len(seqs)
    res = []
    for j in range(L):
        col = [s[j] for s in seqs]
        mean = Fraction(sum(col), n)
        var = Fraction(sum(x * x for x in col), n) - mean * mean
        lo, hi = min(col), max(col)
        # floor(lo - sigma), floor(hi + sigma) exactly
        def floor_minus(base, sign):
            # want floor(base -/+ sigma) with sigma = sqrt(var)
            best = None
            for t in range(base - 2000, base + 2001):
                if sign < 0:
                    v = Fraction(t) - Fraction(base)
                    # t <= base - sigma  <=>  base - t >= sigma
                    d = Fraction(base - t)
                    if d >= 0 and d * d >= var:
                        if best is None or t > best:
                            best = t
                else:
                    d = Fraction(t - base)
                    if d >= 0 and d * d <= var:
                        if best is None or t > best:
                            best = t
            return base if best is None else best
        low = max(0, floor_minus(lo, -1))
        high = min(3028, floor_minus(hi, +1))
        res.append([low, high])
    return res


def row_matches(pattern, values):
    n = real_len(values)
    L = len(pattern)
    for s in range(0, n - L + 1):
        ok = True
        for j in range(L):
            v = values[s + j]
            if not (pattern[j][0] <= v <= pattern[j][1]):
                ok = False
                break
        if ok:
            return True
    return False


def calibrate(clusters, validation, classes, threshold):
    N = [0] * classes
    for r in validation:
        N[r['class']] += 1
    for cl in clusters:
        hits = [0] * classes
        for r in validation:
            if row_matches(cl['range'], r['values']):
                hits[r['class']] += 1
        cl['hits'] = hits
        t = cl['class']
        cin = Fraction(hits[t], N[t])
        cout = Fraction(0)
        for c in range(classes):
            if c != t:
                cout = max(cout, Fraction(hits[c], N[c]))
        cl['score'] = cin / (cout + Fraction(1, 10000))
        cl['kept'] = cl['score'] > Fraction(*threshold)
    kept = sorted([c for c in clusters if c['kept']], key=lambda c: (-c['score'], c['id']))
    return kept


def backup_of(train, width):
    X = []
    y = []
    for r in train:
        vals = list(r['values'][:width])
        while len(vals) < width:
            vals.append(PADDING)
        X.append(vals)
        y.append(r['class'])
    m = DecisionTreeClassifier(max_depth=10, random_state=42, class_weight='balanced')
    m.fit(np.array(X, dtype=np.int64), np.array(y, dtype=np.int64))
    t = m.tree_
    nodes = []
    for i in range(t.node_count):
        if t.children_left[i] == -1:
            v = list(t.value[i][0])
            best = max(range(len(v)), key=lambda k: (v[k], -k))
            nodes.append([int(m.classes_[best])])
        else:
            nodes.append([int(t.feature[i]), int(round(2 * float(t.threshold[i]))),
                          int(t.children_left[i]), int(t.children_right[i])])
    return nodes


def predict(nodes, feats):
    node = 0
    while len(nodes[node]) != 1:
        e = nodes[node]
        node = e[2] if 2 * feats[e[0]] <= e[1] else e[3]
    return nodes[node][0]


def exact_entries(kept, cap):
    limit = cap + 1
    keys = set()
    overflow = False
    for cl in kept:
        L = cl['length']
        ranges = cl['range']
        opts = []
        for j in range(L):
            lo, hi = ranges[j]
            opts.append([v for v in range(lo, hi + 1) if v != PADDING])
        total = 1
        for o in opts:
            total *= len(o)
        if total == 0:
            continue
        if total > limit + 1:
            # cannot enumerate; count via inclusion only when needed
            overflow = True
            break
        for combo in product(*opts):
            keys.add((L, combo))
            if len(keys) > limit:
                overflow = True
                break
        if overflow:
            break
    if overflow:
        # brute force fallback: enumerate everything with a big cap only if small
        allbig = True
        keys = set()
        for cl in kept:
            L = cl['length']
            ranges = cl['range']
            opts = []
            for j in range(L):
                lo, hi = ranges[j]
                opts.append([v for v in range(lo, hi + 1) if v != PADDING])
            total = 1
            for o in opts:
                total *= len(o)
            if total > 200000:
                allbig = False
                break
            for combo in product(*opts):
                keys.add((L, combo))
        if not allbig:
            return None  # cannot determine exactly
        return min(len(keys), cap + 1)
    return min(len(keys), cap + 1)


def run(request):
    cap = request['capacity']
    catalog = []
    banks = {}
    total_frags = 0
    for spec in request['releases']:
        frags = fragments_of(spec['discovery'], spec['width'])
        total_frags += len(frags)
        if total_frags > 4096:
            raise ValueError('too many fragments')
        clusters, noise = cluster(frags, spec['classes'], Fraction(*spec['eps']), spec['ratio'])
        for cl in clusters:
            cl['range'] = intervals_of(cl, frags)
        kept = calibrate(clusters, spec['validation'], spec['classes'], spec['threshold'])
        nodes = backup_of(spec['train'], spec['width'])
        if spec['mode'] == 'range':
            entries = len(kept)
        else:
            entries = exact_entries(kept, cap['exact'])
            if entries is None:
                raise RuntimeError('reference cannot count exact keys')
        catalog.append({
            'id': spec['id'],
            'fragments': [[f['row'], f['start'], f['length']] for f in frags],
            'noise': noise,
            'clusters': [{'id': c['id'], 'class': c['class'], 'members': c['members'],
                          'core': c['core'], 'range': c['range'], 'hits': c['hits'],
                          'score': [c['score'].numerator, c['score'].denominator],
                          'kept': bool(c['kept'])} for c in clusters],
            'priority': [c['id'] for c in kept],
            'backup': nodes,
            'entries': entries,
        })
        banks[spec['id']] = {'spec': spec, 'kept': kept, 'nodes': nodes, 'entries': entries}
    # ---- online replay ----
    current = None
    resident = set()
    pins = {}
    flows = {}
    installs = []
    decisions = []
    at = 0

    def usage(banks_set):
        ur = sum(banks[r]['entries'] for r in banks_set if banks[r]['spec']['mode'] == 'range')
        ue = sum(banks[r]['entries'] for r in banks_set if banks[r]['spec']['mode'] == 'exact')
        return ur, ue

    for block in request['blocks']:
        for op in block:
            kind = op[0]
            if kind == 'install':
                rid = op[1]
                b = banks[rid]
                mode = b['spec']['mode']
                if b['entries'] > cap['range' if mode == 'range' else 'exact']:
                    status = 'oversize'
                else:
                    prev = current
                    evict = prev is not None and prev != rid and pins.get(prev, 0) == 0
                    pros = set(resident)
                    if evict:
                        pros.discard(prev)
                    pros.add(rid)
                    ur, ue = usage(pros)
                    if ur > cap['range'] or ue > cap['exact']:
                        status = 'busy'
                    else:
                        status = 'ok'
                        resident = pros
                        current = rid
                ur, ue = usage(resident)
                installs.append({'at': at, 'id': rid, 'status': status,
                                 'resident': sorted(resident),
                                 'used': {'range': ur, 'exact': ue}})
            elif kind == 'open':
                fid = op[1]
                if current is None:
                    raise ValueError('no current')
                if fid in flows and flows[fid]['active'] is not None:
                    raise ValueError('already open')
                num = 0 if fid not in flows else flows[fid]['count']
                ep = {'flow': fid, 'epoch': num, 'bank': current, 'seq': [],
                      'ts': None, 'dir': None, 'classified': False}
                flows[fid] = {'active': ep, 'count': num + 1}
                pins[current] = pins.get(current, 0) + 1
            elif kind == 'packet':
                fid, ts, src, length = op[1], op[2], op[3], op[4]
                ep = flows.get(fid, {}).get('active')
                if ep is None:
                    raise ValueError('inactive')
                if ep['ts'] is not None and ts < ep['ts']:
                    raise ValueError('ts')
                spec = banks[ep['bank']]['spec']
