                                      'reason': 'close', 'rule': None, 'start': None})
                    ep['classified'] = True
                flows[fid]['active'] = None
                rid = ep['bank']
                pins[rid] -= 1
                if pins[rid] == 0:
                    del pins[rid]
                    if current != rid:
                        resident.discard(rid)
