"""Coverage calibration, exact score filtering, priority and table sizing.

Validation coverage is evaluated with exact rational scores and bitset pattern
matching; the exact bank size is the number of distinct integer keys in the
union of the kept patterns' Cartesian products.
"""
from fractions import Fraction
import numpy as np

PADDING = 1514
VALUE_COUNT = 3029
VALUE_MAX = 3028


def _match_set(prefix, tables, length):
    """Bitmask (by pattern index) of patterns matched by any real-prefix window."""
    accumulated = 0
    first = tables[0]
    span = len(prefix) - length + 1
    for start in range(span):
        current = first[prefix[start]]
        if not current:
            continue
        for coordinate in range(1, length):
            current &= tables[coordinate][prefix[start + coordinate]]
            if not current:
                break
        accumulated |= current
    return accumulated


def _value_tables(patterns, length):
    """Table[coordinate][value] -> bitmask of patterns accepting that value."""
    count = len(patterns)
    values = np.arange(VALUE_COUNT, dtype=np.int64)
    tables = []
    for coordinate in range(length):
        low = np.array([pattern[coordinate][0] for pattern in patterns], dtype=np.int64)
        high = np.array([pattern[coordinate][1] for pattern in patterns], dtype=np.int64)
        accepted = (low[None, :] <= values[:, None]) & (values[:, None] <= high[None, :])
        packed = np.packbits(accepted, axis=1, bitorder='little')
        tables.append([int.from_bytes(packed[index].tobytes(), 'little')
                       for index in range(VALUE_COUNT)])
    return tables


def attach_hits(clusters, validation, classes):
    """Fill hits[c] for every cluster with the matching validation row counts."""
    for cluster in clusters:
        cluster['hits'] = [0] * classes
    rows_by_class = [[] for _ in range(classes)]
    for row in validation:
        prefix = row['values']
        cut = prefix.index(PADDING) if PADDING in prefix else len(prefix)
        if cut:
            rows_by_class[row['class']].append(tuple(prefix[:cut]))
    by_length = {}
    for cluster in clusters:
        by_length.setdefault(cluster['length'], []).append(cluster)
    for length, group in by_length.items():
        count = len(group)
        patterns = [cluster['range'] for cluster in group]
        tables = _value_tables(patterns, length)
        width = (count + 7) // 8
        for label in range(classes):
            hits = np.zeros(count, dtype=np.int64)
            cache = {}
            for prefix in rows_by_class[label]:
                if len(prefix) < length:
                    continue
                found = cache.get(prefix)
                if found is None:
                    found = _match_set(prefix, tables, length)
                    cache[prefix] = found
                if found:
                    bits = np.unpackbits(np.frombuffer(found.to_bytes(width, 'little'),
                                                      dtype=np.uint8),
                                         bitorder='little')[:count]
                    hits += bits
            for index, cluster in enumerate(group):
                cluster['hits'][label] = int(hits[index])


def score_clusters(clusters, validation, classes, threshold):
    """Exact Cin/(Cout+1/10000) score, kept flag and shared priority order."""
    totals = [0] * classes
    for row in validation:
        totals[row['class']] += 1
    limit = Fraction(*threshold)
    for cluster in clusters:
        target = cluster['class']
        inside = Fraction(cluster['hits'][target], totals[target])
        outside = Fraction(0)
        for label in range(classes):
            if label != target and totals[label]:
                share = Fraction(cluster['hits'][label], totals[label])
                if share > outside:
                    outside = share
        cluster['score'] = inside / (outside + Fraction(1, 10000))
        cluster['kept'] = cluster['score'] > limit
    kept = [cluster for cluster in clusters if cluster['kept']]
    kept.sort(key=lambda cluster: (-cluster['score'], cluster['id']))
    return kept


def _factor_size(factor):
    return sum(stop - start + 1 for start, stop in factor)


def _box_size(box):
    size = 1
    for factor in box:
        size *= _factor_size(factor)
    return size


def _split_interval(start, stop):
    """An inclusive interval with the padding value removed from the middle."""
    if start > stop:
        return ()
    if stop < PADDING or start > PADDING:
        return ((start, stop),)
    parts = []
    if start <= PADDING - 1:
        parts.append((start, PADDING - 1))
    if stop >= PADDING + 1:
        parts.append((PADDING + 1, stop))
    return tuple(parts)


def _pattern_box(ranges):
    return tuple(tuple(_split_interval(start, stop)) for start, stop in ranges)


def _interval_union(intervals):
    """Size of the union of a collection of inclusive integer intervals."""
    total = 0
    current = None
    for start, stop in sorted(intervals):
        if current is None:
            current = [start, stop]
        elif start <= current[1] + 1:
            if stop > current[1]:
                current[1] = stop
        else:
            total += current[1] - current[0] + 1
            current = [start, stop]
    if current is not None:
        total += current[1] - current[0] + 1
    return total


def _union_size(boxes, limit, memo):
    """Exact size of the union of boxes, reported as limit+1 when larger."""
    if not boxes:
        return 0
    if len(boxes[0]) == 1:
        size = _interval_union([span for box in boxes for span in box[0]])
        return size if size <= limit else limit + 1
    if len(boxes) == 1:
        size = _box_size(boxes[0])
        return size if size <= limit else limit + 1
    cached = memo.get(boxes)
    if cached is not None:
        return cached
    events = []
    for box in boxes:
        for start, stop in box[0]:
            events.append((start, 1, box))
            events.append((stop + 1, 0, box))
    events.sort(key=lambda event: (event[0], event[1]))
    active = set()
    total = 0
    position = 0
    count = len(events)
    while position < count:
        spot = events[position][0]
        while position < count and events[position][0] == spot:
            _, kind, box = events[position]
            if kind:
                active.add(box)
            else:
                active.discard(box)
            position += 1
        if not active or position == count:
            continue
        span = events[position][0] - spot
        reduced = tuple(sorted({box[1:] for box in active}))
        part = _union_size(reduced, limit, memo)
        if part > limit:
            memo[boxes] = limit + 1
            return limit + 1
        total += span * part
        if total > limit:
            memo[boxes] = limit + 1
            return limit + 1
    memo[boxes] = total
    return total


def exact_key_count(clusters, capacity):
    """Distinct exact keys over every pattern length, clipped to capacity+1."""
    limit = capacity + 1
    by_length = {}
    for cluster in clusters:
        by_length.setdefault(cluster['length'], set()).add(_pattern_box(cluster['range']))
    total = 0
    memo = {}
    for boxes in by_length.values():
        total += _union_size(tuple(sorted(boxes)), limit, memo)
        if total > limit:
            break
    return total if total <= limit else limit

"""Release-bank residency and interleaved flow-epoch online replay.

Atomic installs, eviction of an unreferenced previous bank, pinning by open
epochs (including classified ones), direction fixing, idle/segment/limit/close
commitment and the final residency snapshot all live here.
"""
from online_matching.match_p4 import BankMatcher

PADDING = 1514


class Epoch:
    """One open epoch of a flow; it pins the release current at open time."""

    __slots__ = ('flow', 'number', 'bank', 'matcher', 'stream', 'offset',
                 'consumed', 'last_ts', 'direction', 'classified')

    def __init__(self, flow, number, bank):
        self.flow = flow
        self.number = number
        self.bank = bank
        self.matcher = bank.matcher()
        self.offset = self.matcher.span
        self.stream = [PADDING] * self.offset
        self.consumed = 0
        self.last_ts = None
        self.direction = None
        self.classified = False

    def features(self):
        """First width encoded features, right padded when shorter."""
        width = self.bank.width
        values = self.stream[self.offset:self.offset + width]
        if len(values) < width:
            values = list(values) + [PADDING] * (width - len(values))
        return values


class SessionEngine:
    """Drives install/open/packet/close operations over the release banks."""

    def __init__(self, banks, capacity):
        self.banks = banks
        self.capacity = capacity
        self.current = None
        self.resident = set()
        self.pins = {}
        self.flows = {}
        self.installs = []
        self.decisions = []

    # ---- bank residency ------------------------------------------------
    def _usage(self, banks):
        used_range = 0
        used_exact = 0
        for release in banks:
            bank = self.banks[release]
            if bank.mode == 'range':
                used_range += bank.entries
            else:
                used_exact += bank.entries
        return used_range, used_exact

    def _snapshot(self):
        used_range, used_exact = self._usage(self.resident)
        return {'resident': sorted(self.resident),
                'used': {'range': used_range, 'exact': used_exact}}

    def install(self, release, at):
        bank = self.banks[release]
        limit = self.capacity['range' if bank.mode == 'range' else 'exact']
        if bank.entries > limit:
            status = 'oversize'
        else:
            previous = self.current
            evict = (previous is not None and previous != release and
                     not self.pins.get(previous, 0))
            prospective = set(self.resident)
            if evict:
                prospective.discard(previous)
            prospective.add(release)
            used_range, used_exact = self._usage(prospective)
            if used_range > self.capacity['range'] or used_exact > self.capacity['exact']:
                status = 'busy'
            else:
                status = 'ok'
                self.resident = prospective
                self.current = release
        snapshot = self._snapshot()
        self.installs.append({'at': at, 'id': release, 'status': status,
                              'resident': snapshot['resident'],
                              'used': snapshot['used']})

    # ---- epoch lifecycle -----------------------------------------------
    def open(self, flow, at):
        if self.current is None:
            raise ValueError('open without a current release')
        record = self.flows.get(flow)
        if record is not None and record[0] is not None:
            raise ValueError('open of an active flow')
        number = 0 if record is None else record[1]
        epoch = Epoch(flow, number, self.banks[self.current])
        self.flows[flow] = (epoch, number + 1)
        release = epoch.bank.id
        self.pins[release] = self.pins.get(release, 0) + 1

    def _commit(self, epoch, reason, at, seen, cluster, label, start):
        self.decisions.append({'flow': epoch.flow, 'epoch': epoch.number,
                               'release': epoch.bank.id, 'at': at, 'seen': seen,
                               'class': label, 'reason': reason,
                               'rule': cluster, 'start': start})
        epoch.classified = True

    def _classify_backup(self, epoch, reason, at, seen):
        label = epoch.bank.predict(epoch.features())
        self._commit(epoch, reason, at, seen, None, label, None)

    def packet(self, flow, timestamp, source, length, at):
        record = self.flows.get(flow)
        epoch = record[0] if record is not None else None
        if epoch is None:
            raise ValueError('packet for an inactive flow')
        if epoch.last_ts is not None and timestamp < epoch.last_ts:
            raise ValueError('decreasing timestamp in an epoch')
        if not epoch.classified:
            bank = epoch.bank
            if (epoch.consumed >= bank.width and epoch.last_ts is not None and
                    timestamp - epoch.last_ts > bank.idle_us):
                # idle backup wins before the arriving packet is consumed
                self._classify_backup(epoch, 'idle', at, epoch.consumed)
            else:
                self._consume(epoch, source, length)
                if not epoch.classified:
                    found = epoch.matcher.suffix_match(epoch.stream,
                                                       len(epoch.stream) - 1)
                    if found is not None:
                        rank, size = found
                        pattern = bank.patterns[rank]
                        self._commit(epoch, 'segment', at, epoch.consumed,
                                     pattern[2], pattern[3], epoch.consumed - size)
                    elif epoch.consumed > bank.packet_limit:
                        self._classify_backup(epoch, 'limit', at, epoch.consumed)
        epoch.last_ts = timestamp

    def _consume(self, epoch, source, length):
        if epoch.direction is None:
            epoch.direction = source
        if source == epoch.direction:
            epoch.stream.append(PADDING + length)
        else:
            epoch.stream.append(PADDING - length)
        epoch.consumed += 1

    def close(self, flow, at):
        record = self.flows.get(flow)
        epoch = record[0] if record is not None else None
        if epoch is None:
            raise ValueError('close of an inactive flow')
        if not epoch.classified:
            self._classify_backup(epoch, 'close', at, epoch.consumed)
        self.flows[flow] = (None, record[1])
        release = epoch.bank.id
        remaining = self.pins.get(release, 0) - 1
        if remaining:
            self.pins[release] = remaining
        else:
            self.pins.pop(release, None)
            if self.current != release:
                self.resident.discard(release)

    # ---- driver --------------------------------------------------------
    def run(self, blocks):
        at = 0
        for block in blocks:
            for event in block:
                kind = event[0]
                if kind == 'install':
                    self.install(event[1], at)
                elif kind == 'open':
                    self.open(event[1], at)
                elif kind == 'packet':
                    self.packet(event[1], event[2], event[3], event[4], at)
                else:
                    self.close(event[1], at)
                at += 1
        for record in self.flows.values():
            if record[0] is not None:
                raise ValueError('flow left open at the end of the request')
        final = {'current': self.current}
        final.update(self._snapshot())
        return self.installs, self.decisions, final

